SourceCode.Declaration:
/// <summary>
/// Wave ID on sales and transfer order screens.
/// One-off script that stamps the latest wave ID on existing sales orders, transfer orders and
/// shipment load lines for waves extracted on or after the selected date.
/// Run per legal entity: https://[environment]/?mi=SysClassRunner&amp;cls=METWaveIdBackfillScript
/// </summary>
/// <remarks>
/// Waves are processed oldest first, so an order that belongs to several waves ends up with the latest one.
/// Each order is stamped with set-based updates in its own transaction.
/// </remarks>
internal final class METWaveIdBackfillScript
{
}

Method.Source:
/// <summary>
/// Class entry point.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    Dialog          dialog = new Dialog("@MET:WaveId");
    DialogField     fromDateField = dialog.addFieldValue(extendedTypeStr(FromDate), DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - 30);

    if (!dialog.run())
    {
        return;
    }

    FromDate    fromDate = fromDateField.value();
    utcdatetime fromDateTime = DateTimeUtil::newDateTime(fromDate, 0, DateTimeUtil::getUserPreferredTimeZone());

    METWaveTable    waveTable;
    METWaveLine     waveLine;
    int             waveCount, orderCount;

    while select WaveId from waveTable
        order by OrderExtractDateTime, WaveId
        where waveTable.OrderExtractDateTime >= fromDateTime
    {
        while select DocumentNumber, Type from waveLine
            group by DocumentNumber, Type
            where waveLine.WaveId == waveTable.WaveId
        {
            if (waveLine.Type == METType::SalesOrder)
            {
                METWaveIdStampHelper::stampSalesOrder(waveTable.WaveId, waveLine.DocumentNumber);
            }
            else if (waveLine.Type == METType::TransferOrder)
            {
                METWaveIdStampHelper::stampTransferOrder(waveTable.WaveId, waveLine.DocumentNumber);
            }

            orderCount++;
        }

        waveCount++;
    }

    info(strFmt("%1: %2 / %3", curExt(), waveCount, orderCount));
}
